{
  "roles": [
    {
      "role": "billing",
      "description": "A billing staff member creates and updates invoices, insurance claims, and payment plans for patient care. They check coverage, balances, and claim status, then act on discrepancies by contacting payers or patients. They also resolve billing questions and record payment or financial assistance decisions."
    },
    {
      "role": "clinician",
      "description": "A clinician assesses patients, makes diagnoses, and documents clinical findings and treatment plans. They order tests, prescribe or adjust treatments, and decide on care pathways. They also review lab and medication information to guide ongoing medical decisions."
    },
    {
      "role": "lab_tech",
      "description": "A lab technician collects, processes, and tests patient specimens according to ordered procedures. They check equipment and quality controls, then record and validate result values. They flag abnormal or critical results for clinical review."
    },
    {
      "role": "nurse",
      "description": "A nurse monitors patients, records vital signs and observations, and administers prescribed care. They check medication schedules, report changes in condition, and document nursing assessments. They also educate patients and families about care plans and safety."
    },
    {
      "role": "pharmacist",
      "description": "A pharmacist verifies prescriptions, checks allergies and drug interactions, and dispenses medications. They review dosing, supply, and insurance or billing details where relevant. They counsel patients on use, side effects, and adherence."
    },
    {
      "role": "reception",
      "description": "A receptionist greets patients, verifies identity, and collects or updates contact and insurance information. They check appointment details, direct patients, and handle routine administrative questions. They create or update front-desk records and hand off issues to schedulers or billing."
    },
    {
      "role": "scheduler",
      "description": "A scheduler coordinates patient appointments, checks provider availability, and books or reschedules visits. They send reminders and track no-shows or cancellations. They update scheduling records and communicate logistics to patients and care teams."
    },
    {
      "role": "social_worker",
      "description": "A social worker assesses psychosocial needs, barriers to care, and family or community support. They document assessments, connect patients to resources, and coordinate with other staff. They decide on referrals and follow up on social or practical care needs."
    }
  ],
  "information_kinds": [
    {
      "name": "patient_identifiers",
      "description": "Unique and contact details used to identify a patient, such as name, date of birth, MRN, address, phone, and insurance identifiers."
    },
    {
      "name": "patient_summaries",
      "description": "High-level overviews of general care status, visit frequency, and broad needs."
    },
    {
      "name": "health_records",
      "description": "Clinical information about symptoms, diagnoses, assessments, treatment plans, progress notes, and care decisions."
    },
    {
      "name": "lab_results",
      "description": "Specimen test data, values, units, reference ranges, and technician or reviewer notes about laboratory findings."
    },
    {
      "name": "medication_records",
      "description": "Prescriptions, doses, allergies, dispensing history, interactions, and medication management notes."
    },
    {
      "name": "billing_financial_records",
      "description": "Invoices, insurance claims, payments, balances, coverage details, and financial assistance or dispute information."
    },
    {
      "name": "appointment_scheduling",
      "description": "Visit dates, times, provider availability, reminders, cancellations, and rescheduling details."
    },
    {
      "name": "care_team_assignments",
      "description": "Relationship facts identifying which staff members are assigned to a patient for clinical or care roles."
    },
    {
      "name": "consent_records",
      "description": "Explicit owner consents, their scope, validity period, and revocation status for sharing specific details."
    },
    {
      "name": "social_work_notes",
      "description": "Psychosocial assessments, resource referrals, family or community support details, and barriers to care."
    }
  ]
}

